66	      const r = await (await clerkClient()).organizations.getOrganizationMembershipList({ organizationId: orgId, userId: [userId], limit: 1 });
67	      return r.data.find(x => x.organization.id === orgId && x.publicUserData?.userId === userId)?.role ?? null;
