107	    if (!oauth) throw new AgentError(401, "invalid_token", "REST requires a workspace API token. OAuth access tokens are accepted only at /mcp.");
108	    const bearer = /^Bearer ([^\s]+)$/i.exec(header ?? "");
109	    const identity = bearer ? await deps.verify(bearer[1]) : null;
