16	  const {data:activity,error}=await db().from("agent_activity").select("id,client,tool,resource_id,created_at").eq("workspace_id",member.workspace.id).order("created_at",{ascending:false}).order("id").limit(100);
17	  if(error) throw new Error("Activity could not be loaded");
